// Lista forms que devem ser deletados
const helpers = this.helpers;
const baseUrl = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;
const I_FORM = 'Glpi%5CForm%5CForm';

const nomes = [
  'Criacao de Usuario','Reset de Senha','Reativacao de Usuario','Desativacao de Usuario',
  'Acesso a Pasta de Rede','Criacao de E-mail Institucional','Transferencia de Setor ou Local',
  'Manutencao de Impressoras','Manutencao de Computador','Instalacao de Software',
  'Atualizacao de Software','Reparacao de Software','Internet Lenta ou Instavel',
  'Sem Conexao com a Internet','Acesso Wi-Fi','VPN / Acesso Remoto','Outros Assuntos de Rede',
  'Cartucho ou Toner','Saude - Problemas de Acesso','Saude - Novo Acesso','Saude - Solicitacoes Gerais',
  'Telefonia - Problemas com Ramal','Telefonia - Aparelho Telefonico','Telefonia - Celular e Chip',
  'Telefonia - Outros'
];

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

const r0 = await callRaw('GET', `${baseUrl}/initSession`, {
  'App-Token': appToken,
  'Authorization': `user_token ${userToken}`
});
if (r0.status !== 200) return [{ json: { erro: 'auth falhou' }}];
const sessionToken = r0.body.session_token;
const H = { 'App-Token': appToken, 'Session-Token': sessionToken };

const formsAlvo = [];
for (const isDel of [0, 1]) {
  const r = await callRaw('GET', `${baseUrl}/${I_FORM}?is_deleted=${isDel}&range=0-200`, H);
  const arr = Array.isArray(r.body) ? r.body : (r.body && r.body.data ? r.body.data : []);
  for (const f of arr) {
    if (!f || !f.id || !f.name) continue;
    if (nomes.includes(f.name) || f.name.startsWith('ZTESTE-')) {
      formsAlvo.push({ id: f.id, name: f.name, is_deleted: isDel });
    }
  }
}

await callRaw('GET', `${baseUrl}/killSession`, H);
return formsAlvo.map(f => ({ json: f }));

// Deleta 1 form (1 item por execucao via SplitInBatches)
const helpers = this.helpers;
const baseUrl = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;
const I_FORM = 'Glpi%5CForm%5CForm';

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

const f = $input.first().json;

const r0 = await callRaw('GET', `${baseUrl}/initSession`, {
  'App-Token': appToken,
  'Authorization': `user_token ${userToken}`
});
if (r0.status !== 200) return [{ json: { ...f, status: 'erro_auth' }}];
const sessionToken = r0.body.session_token;
const H = { 'App-Token': appToken, 'Session-Token': sessionToken };

const del = await callRaw('DELETE', `${baseUrl}/${I_FORM}/${f.id}?force_purge=1`, H);
await callRaw('GET', `${baseUrl}/killSession`, H);

return [{ json: {
  ...f,
  status: del.status >= 400 ? `falha_${del.status}` : 'purgado',
  delete_status: del.status
}}];

// Resumo (executa apos o loop terminar)
const items = $input.all().map(i => i.json);
const purgados = items.filter(x => x.status === 'purgado').length;
const falhas = items.filter(x => x.status && x.status.startsWith('falha')).length;
return [{ json: {
  sucesso: falhas === 0,
  total: items.length,
  purgados,
  falhas,
  items
}}];

